 * Get the top recurring violation patterns across all surfaces.
 */
export async function getTopPatterns(limit: number = 10): Promise<Array<{
  violationType: string;
  surface: string;
  occurrenceCount: number;
  autoFixedCount: number;
  manualFixedCount: number;
  revertedCount: number;
  avgSeverity: string | null;
  firstSeen: Date;
  lastSeen: Date;
  suggestedPrevention: string | null;
}>> {
  const db = await getDb();
  if (!db) return [];
  const patterns = await db.select()
    .from(violationPatterns)
    .orderBy(desc(violationPatterns.occurrenceCount))
    .limit(limit);

  return patterns.map(p => ({
    violationType: p.violationType,
    surface: p.surface,
    occurrenceCount: p.occurrenceCount,
    autoFixedCount: p.autoFixedCount,
    manualFixedCount: p.manualFixedCount,
    revertedCount: p.revertedCount,
    avgSeverity: p.avgSeverity,
    firstSeen: p.firstSeen,
    lastSeen: p.lastSeen,
    suggestedPrevention: p.suggestedPrevention,
  }));
}

/**
 * Generate prevention advice for a pattern using Claude.
 */
export async function generatePreventionAdvice(patternId: string): Promise<string> {
  const db = await getDb();
  if (!db) return 'Database not available.';
  const pattern = await db.select()
    .from(violationPatterns)
    .where(eq(violationPatterns.patternId, patternId))
    .limit(1);

  if (pattern.length === 0) return 'Pattern not found.';

  const p = pattern[0];
  const govResult = await governedGenerate({
    messages: [
      {
        role: 'system',
        content: 'You are a governance advisor. Given a recurring violation pattern, suggest a concrete prevention strategy in 2-3 sentences.',
      },
      {
        role: 'user',
        content: `Violation type: ${p.violationType}\nSurface: ${p.surface}\nOccurrences: ${p.occurrenceCount}\nAuto-fixed: ${p.autoFixedCount}\nManual-fixed: ${p.manualFixedCount}\nReverted: ${p.revertedCount}\nSample content: ${p.commonContent || 'N/A'}\n\nWhat should be done to prevent this from recurring?`,
      },
    ],
    contentType: 'generation',
    contentRole: 'user-facing',
    productId: 'services',
    surfaceId: 'services-organizational-memory',
  });

  const rawAdvice = (govResult as unknown as Record<string, unknown>).choices?.[0]?.message?.content;
  const advice = typeof rawAdvice === 'string' ? rawAdvice : 'Unable to generate advice.';

  // Persist the advice
  await db.update(violationPatterns)
    .set({ suggestedPrevention: advice, updatedAt: new Date() })
    .where(eq(violationPatterns.patternId, patternId));

  return advice as string;
}

